/* Optional, first-party audience measurement. No form values or query strings. */
let audienceConsent='unknown',audienceVisitor='',audienceSession='',audiencePage='',audienceSince=0;
try{audienceConsent=localStorage.getItem('lex-audience-consent')||'unknown';}catch{}
const audienceAllowed=()=>audienceConsent==='yes'&&!['owner','admin','editor'].includes(state.user?.role)&&navigator.doNotTrack!=='1'&&!navigator.globalPrivacyControl;
function audienceIds(){try{const month=new Date().toISOString().slice(0,7);let stored=JSON.parse(localStorage.getItem('lex-audience-visitor')||'null');if(!stored||stored.month!==month){stored={id:crypto.randomUUID(),month};localStorage.setItem('lex-audience-visitor',JSON.stringify(stored));}audienceVisitor=stored.id;let session=JSON.parse(sessionStorage.getItem('lex-audience-session')||'null');if(!session||Date.now()-session.time>1800000)session={id:crypto.randomUUID()};session.time=Date.now();sessionStorage.setItem('lex-audience-session',JSON.stringify(session));audienceSession=session.id;return true;}catch{return false;}}
function audienceSend(event,page,target='',seconds=0){if(!audienceAllowed()||!page||!audienceIds())return;fetch('/api/visit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({consent:true,visitor:audienceVisitor,session:audienceSession,event,page,target,seconds}),keepalive:true}).catch(()=>{});}
function audiencePath(){const path=(currentRoute()).split('?')[0];return /^\/(administration|compte|connexion|inscription|panier|paiement|juridique)(\/|$)/.test(path)?'':path;}
function audienceEnd(){if(audiencePage&&audienceSince){const seconds=Math.min(120,Math.floor((Date.now()-audienceSince)/1000));if(seconds>0)audienceSend('engagement',audiencePage,'',seconds);}audienceSince=0;}
function audienceStart(){audienceEnd();audiencePage=audiencePath();if(audiencePage&&document.visibilityState==='visible'){audienceSend('view',audiencePage);audienceSince=Date.now();}}
function consentPanel(){if($('#audience-consent'))return;const el=document.createElement('aside');el.id='audience-consent';el.setAttribute('aria-label','Mesure de fréquentation');el.innerHTML='<p><b>Nous aider à améliorer le site</b><br>Acceptez-vous une mesure locale des pages consultées, des clics et du temps actif ? Aucun contenu de formulaire n’est collecté. Vous pouvez refuser et continuer à naviguer.</p><div class="actions"><button class="btn small" data-consent="yes">Accepter</button><button class="btn outline small" data-consent="no">Refuser</button></div>';document.body.append(el);$$('[data-consent]',el).forEach(b=>b.onclick=()=>{audienceEnd();audienceConsent=b.dataset.consent;try{localStorage.setItem('lex-audience-consent',audienceConsent);if(audienceConsent==='no'){localStorage.removeItem('lex-audience-visitor');sessionStorage.removeItem('lex-audience-session');}}catch{}el.remove();if(audienceConsent==='yes')audienceStart();});}
const originalShell=shell;shell=function(){originalShell();$('.footer-bottom').insertAdjacentHTML('beforeend','<button class="text-link" id="audience-settings">Préférences de confidentialité</button>');$('#audience-settings').onclick=consentPanel;if(audienceConsent==='unknown'&&!['owner','admin','editor'].includes(state.user?.role)&&audiencePath())consentPanel();if(['owner','admin','editor'].includes(state.user?.role))$('#audience-consent')?.remove();};
window.addEventListener('hashchange',audienceStart);
window.addEventListener('pagehide',audienceEnd);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')audienceEnd();else if(audiencePage)audienceSince=Date.now();});
setInterval(()=>{if(document.visibilityState==='visible'){audienceEnd();if(audiencePage)audienceSince=Date.now();}},30000);
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="/"]');if(a&&audiencePage){const target=a.getAttribute('href').split('?')[0];if(!/^\/(administration|compte|connexion|inscription|panier|paiement)/.test(target))audienceSend('click',audiencePage,target);}});
// Wait for the first bootstrap so administrator visits are excluded.
const originalRefresh=refresh;refresh=async function(){await originalRefresh();if(!audiencePage)audienceStart();};

refresh().then(render).catch(err=>{main.innerHTML=`<section class="wrap section"><h1>LEX ASSOCIÉS</h1><p>${esc(err.message)}</p><p>Relancez le serveur local de la plateforme, puis actualisez cette page.</p></section>`;});
